   100→
   101→.input {
   102→  flex: 1;
   103→  padding: 0.65rem 1rem;
   104→  border: 1.5px solid #c9cccf;
   105→  border-radius: 8px;
   106→  font-size: 0.95rem;
   107→  color: #202223;
