   194→@media (max-width: 768px) {
   195→  .features {
   196→    grid-template-columns: repeat(2, 1fr);
   197→  }
   198→
   199→  .formRow {
   200→    flex-direction: column;
   201→  }
   202→
   203→  .button {
   204→    width: 100%;
   205→  }
   206→}
   207→
   208→@media (max-width: 480px) {
